import os


class Config:
    # --------------------------------------------------------------------------
    # Directory & File Paths
    # --------------------------------------------------------------------------
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    # Working directory for caching processed data and saving models
    WORKING_DIR = "./working/idea_32"

    # Ensure the working directory exists
    os.makedirs(WORKING_DIR, exist_ok=True)

    # Metadata Paths (Generated by the provided script)
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Raw Data Paths
    TRAIN_DATA_PATH = os.path.join(INPUT_DIR, "train.csv")
    TEST_DATA_PATH = os.path.join(INPUT_DIR, "test.csv")
    SAMPLE_SUBMISSION_PATH = os.path.join(INPUT_DIR, "sample_submission.csv")

    # Output Paths
    CACHE_FILE_PATH = os.path.join(WORKING_DIR, "processed_data.npz")
    MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "best_model.pth")
    SUBMISSION_PATH = os.path.join(WORKING_DIR, "submission.csv")

    # --------------------------------------------------------------------------
    # Global Settings
    # --------------------------------------------------------------------------
    SEED = 42
    NUM_WORKERS = 4  # Optimized for the 12 vCPU environment
    DEVICE = "cuda"  # Will be checked in training script, but default preference is GPU

    # Debugging / Development
    # If True, datasets will be truncated to DEBUG_SAMPLES for rapid iteration
    DEBUG = False
    DEBUG_SAMPLES = 5000

    # --------------------------------------------------------------------------
    # Data Parameters
    # --------------------------------------------------------------------------
    # f_27 is a string of length 10
    SEQ_LEN = 10
    # Vocabulary size for characters (A-Z).
    # 26 letters + 1 for potential padding/unknown = 27.
    # Using 30 as a safe upper bound.
    VOCAB_SIZE = 30
    # Number of continuous features (f_00 to f_30, excluding f_27)
    NUM_CONT_FEATURES = 30

    # --------------------------------------------------------------------------
    # Model Architecture Parameters
    # --------------------------------------------------------------------------
    # Stream 1: Categorical (Transformer)
    EMBED_DIM = 32
    TRANSFORMER_LAYERS = 2
    TRANSFORMER_HEADS = 4
    TRANSFORMER_DROPOUT = 0.1
    TRANSFORMER_ACTIVATION = "gelu"
    TRANSFORMER_NORM_FIRST = False  # Post-Norm

    # Positional Embeddings
    # Initialization standard deviation for absolute positional embeddings
    POS_EMBED_STD = 0.02

    # Stream 2 & Fusion
    # The dimension to project continuous features to before fusion
    # and the dimension of the sequence stem output
    STEM_DIM = (
        64  # Intermediate dim for stems before fusion (optional, or match backbone)
    )

    # Backbone (SwiGLU ResFunnel)
    # The fusion layer projects to the first stage width
    BACKBONE_STAGES = [512, 256, 128]
    BLOCKS_PER_STAGE = 3

    # Regularization
    MAIN_DROPOUT = 0.35
    STOCHASTIC_DEPTH_MIN = 0.0
    STOCHASTIC_DEPTH_MAX = 0.2

    # --------------------------------------------------------------------------
    # Training Parameters
    # --------------------------------------------------------------------------
    BATCH_SIZE = 1024
    EPOCHS = 40

    # Optimizer (AdamW)
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY_ENCODER = 1e-2  # For weights
    WEIGHT_DECAY_BIAS = 0.0  # For biases, LayerNorms, PosEmbeds

    # Scheduler (Step Decay)
    SCHEDULER_STEP_SIZE = 10
    SCHEDULER_GAMMA = 0.1

    # Early Stopping
    EARLY_STOPPING_PATIENCE = 10
    EARLY_STOPPING_MIN_DELTA = 1e-5
